:root {
  --cream: #f5efe0;
  --parchment: #e8d9b5;
  --rust: #9b3a1a;
  --rust-light: #c05a2e;
  --brown-dark: #3d2008;
  --brown-mid: #6b3a1f;
  --olive: #6b7a2e;
  --olive-light: #9aab3f;
  --gold: #c89a2e;
  --gold-light: #e8bf5a;
  --ink: #2a1a08;
  --divider: #c8a96e;
}

article.cider-card {
  background-color: var(--cream);
  border: 3px solid var(--rust);
  border-radius: 6px;
  width: 460px;
  padding: 0;
  overflow: hidden;
  font-size: 13px;
  color: var(--ink);
}

.card-header {
  background-color: var(--rust);
  padding: 14px 20px 12px;
  text-align: center;
  border-bottom: 3px solid var(--gold);
}

.season-badge {
  display: inline-block;
  background-color: var(--gold);
  color: var(--brown-dark);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 3px 12px;
  border-radius: 20px;
  margin-bottom: 6px;
}

.card-title {
  font-size: 22px;
  font-weight: 800;
  color: var(--cream);
  margin: 0 0 3px;
  letter-spacing: 0.04em;
  line-height: 1.1;
}

.card-subtitle {
  font-size: 11px;
  color: var(--gold-light);
  margin: 0;
  letter-spacing: 0.08em;
}

.order-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-bottom: 2px dashed var(--divider);
  background-color: var(--parchment);
}

.variety-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 14px 18px;
  margin: 0;
}

.variety-block:first-child {
  border-right: 2px dashed var(--divider);
}

.variety-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--rust-light);
}

.variety-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--brown-dark);
  line-height: 1.2;
}

.variety-note {
  font-size: 11px;
  color: var(--brown-mid);
  font-style: italic;
}

.details-row {
  display: flex;
  justify-content: space-between;
  padding: 12px 20px;
  background-color: var(--cream);
  border-bottom: 2px solid var(--divider);
  gap: 8px;
}

.detail-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  flex: 1;
}

.detail-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--olive);
}

.detail-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--brown-dark);
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 20px;
  background-color: var(--parchment);
}

.footer-stamp {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--olive);
  border: 2px solid var(--olive-light);
  border-radius: 4px;
  padding: 3px 10px;
}

.footer-note {
  font-size: 11px;
  color: var(--brown-mid);
  font-style: italic;
  margin: 0;
  text-align: center;
}

.footer-mark {
  font-size: 16px;
  color: var(--gold);
}
